STORY = [('muranishi', '我々は衛星チャンネル開局に向けて大きく前進した。これを機に一気に攻勢を仕掛ける。', "We just took a giant leap toward launching our satellite channel. Let's seize this moment and go on the offensive.", [(587, '衛星チャンネル 開局に向けて'), (588, '大きく前進した'), (589, 'これを機に 一気に攻勢を仕掛ける')], ''), ('muranishi', 'まずは開局決定のリリースをマスコミに送る。人生はやったもん勝ちだ。', "First we'll send the press a release announcing our launch. In life, whoever moves first wins.", [(590, 'まずは 開局決定のリリースを マスコミに送る'), (592, '人生は やったもん勝ちだ')], ''), ('muranishi', 'そこで第一作目として、今世紀最大の傑作を撮影する！', 'And for our very first production, we will film the greatest masterpiece of the century!', [(593, 'そこで 第１作目として'), (594, '今世紀最大の傑作を撮影する')], 'spelled numeral in kanji'), ('muranishi', 'これはもちろん無許可での撮影になる。', 'Naturally, we will be filming this without a permit.', [(604, 'これは もちろん 無許可での撮影になる')], ''), ('muranishi', 'リムジン八台に女優、男優、助監督を乗せてスタート地点へ向かう。', 'Eight limousines carrying actresses, actors, and assistant directors will head to the starting line.', [(606, 'リムジン８台に 女優 男優 助監督を乗せて'), (607, 'スタート地点へ向かう')], 'spelled numeral in kanji'), ('muranishi', 'これをカメラカー二台とヘリ二台で一気に撮影する！', "We'll shoot the whole thing in one sweep with two camera cars and two helicopters!", [(616, 'これをカメラカー２台と ヘリ２台で'), (617, '一気に撮影する')], 'spelled numerals in kanji'), ('muranishi', '通報を受けてからパトカーが到着するまで二十分かかる。', 'Once a call goes in, it takes twenty minutes for police cars to arrive.', [(628, '通報を受けてから パトカーが 到着するまで20分かかる')], 'spelled numeral in kanji'), ('muranishi', 'この二十分の間にすべてを撮りきって逃げる！', 'Within those twenty minutes, we shoot everything and bolt!', [(629, 'この20分の間に すべてを撮りきって 逃げる')], 'spelled numeral in kanji'), ('muranishi', '俺は今冷静に見えるだろうが、実は非常に興奮してる。', 'I probably look calm right now, but inside I am tremendously excited.', [(634, '俺は今 冷静に見えるだろうが'), (635, '実は 非常に興奮してる')], ''), ('student', 'ヘリとリムジンを発注するんですけど、全部で二十作品分の予算になっちゃうんですよ。', "We're ordering the helicopters and limousines, but the total comes to the budget of twenty videos.", [(643, 'ヘリとリムジンを 発注するんですけど'), (645, '全部で 20作品分の予算に なっちゃうんですよ')], 'spelled numeral in kanji'), ('reika', 'えっ？なんとかします。他の諸経費からつじつま合わせときます。', "What? I'll make it work somehow. I'll balance the shortfall out of other expenses.", [(646, 'えっ'), (647, 'なんとかします'), (648, '他の諸経費から つじつま合わせときます')], ''), ('reika', 'ちょっと見せてください。これぐらいの金額だったら多分…', 'Let me take a look at that. With an amount around this size, maybe...', [(649, 'ちょっと見せてください'), (650, 'これぐらいの金額だったら 多分')], '')]
